CREATE OR REPLACE FUNCTION public.handle_first_admin() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN RETURN NEW; END $$;
COMMENT ON FUNCTION public.handle_first_admin() IS 'Public signup never grants roles; administrators are explicitly provisioned by the operator.';
REVOKE UPDATE ON public.issues FROM anon,authenticated;
DO $$ DECLARE cols text; BEGIN SELECT string_agg(quote_ident(attname),',') INTO cols FROM pg_attribute WHERE attrelid='public.issues'::regclass AND attnum>0 AND NOT attisdropped; EXECUTE 'REVOKE UPDATE ('||cols||') ON public.issues FROM anon, authenticated'; END $$;
DROP POLICY IF EXISTS "issues public read" ON public.issues;
CREATE POLICY "staff case reads" ON public.issues FOR SELECT TO authenticated USING(public.is_staff(auth.uid()));
REVOKE SELECT ON public.issues FROM anon;
DROP POLICY IF EXISTS "events public read" ON public.issue_events;
CREATE POLICY "staff event reads" ON public.issue_events FOR SELECT TO authenticated USING(public.is_staff(auth.uid()));
REVOKE SELECT ON public.issue_events FROM anon;
DROP POLICY IF EXISTS "public assignment history" ON public.issue_assignments;
CREATE POLICY "staff assignment history" ON public.issue_assignments FOR SELECT TO authenticated USING(public.is_staff(auth.uid()));
REVOKE SELECT ON public.issue_assignments FROM anon;
ALTER TABLE public.issue_secrets ADD COLUMN token_hash text;
UPDATE public.issue_secrets SET token_hash=encode(sha256(convert_to(recovery_token,'UTF8')),'hex'),recovery_token='[hashed]' WHERE token_hash IS NULL;
COMMENT ON COLUMN public.issue_secrets.recovery_token IS 'DEPRECATED: raw credentials are discarded; token_hash validates reporter capabilities.';
CREATE OR REPLACE FUNCTION public.hash_reporter_token() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF NEW.recovery_token <> '[hashed]' THEN NEW.token_hash:=encode(sha256(convert_to(NEW.recovery_token,'UTF8')),'hex'); NEW.recovery_token:='[hashed]'; END IF; RETURN NEW; END $$;
CREATE TRIGGER hash_reporter_token BEFORE INSERT OR UPDATE ON public.issue_secrets FOR EACH ROW EXECUTE FUNCTION public.hash_reporter_token();
CREATE OR REPLACE FUNCTION public.verify_reporter_token(_ref text,_token text) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT length(_token)=48 AND _token ~ '^[a-f0-9]{48}$' AND EXISTS(SELECT 1 FROM public.issue_secrets s JOIN public.issues i ON i.id=s.issue_id WHERE i.ref_code=_ref AND s.token_hash=encode(sha256(convert_to(_token,'UTF8')),'hex')) $$;
REVOKE ALL ON FUNCTION public.verify_reporter_token(text,text) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.verify_reporter_token(text,text) TO service_role;
CREATE OR REPLACE FUNCTION public.citizen_change_issue(_ref text,_token text,_action text,_note text) RETURNS text LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE r public.issues; next_status public.issue_status; BEGIN SELECT * INTO r FROM public.issues WHERE ref_code=_ref FOR UPDATE; IF r.id IS NULL OR NOT public.verify_reporter_token(_ref,_token) THEN RAISE EXCEPTION 'This tracking link is not valid'; END IF; IF r.status<>'resolved' THEN RAISE EXCEPTION 'This action is only available after resolution'; END IF; IF _action NOT IN ('confirm','reopen') OR length(coalesce(_note,''))>500 THEN RAISE EXCEPTION 'Invalid reporter action'; END IF; next_status:=CASE WHEN _action='confirm' THEN 'closed'::public.issue_status ELSE 'reopened'::public.issue_status END; UPDATE public.issues SET status=next_status WHERE id=r.id; INSERT INTO public.issue_events(issue_id,kind,from_status,to_status,actor_label,note) VALUES(r.id,CASE WHEN _action='confirm' THEN 'citizen_confirmed' ELSE 'disputed' END,'resolved',next_status,'Original reporter',CASE WHEN _action='confirm' THEN 'Reporter confirmed the fix' ELSE 'Reporter requested another review' END); RETURN next_status::text; END $$;
CREATE TABLE public.issue_photos(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),issue_id uuid NOT NULL REFERENCES public.issues(id),original_path text NOT NULL,display_path text NOT NULL,annotated_path text,source text NOT NULL DEFAULT 'gallery',metadata jsonb NOT NULL DEFAULT '{}'::jsonb,original_sha256 text NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.issue_photos TO authenticated;
GRANT ALL ON public.issue_photos TO service_role;
ALTER TABLE public.issue_photos ENABLE ROW LEVEL SECURITY;
CREATE POLICY "staff read photo originals" ON public.issue_photos FOR SELECT TO authenticated USING(public.is_staff(auth.uid()));
CREATE OR REPLACE FUNCTION public.attach_report_photo() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF length(coalesce(NEW.original_path,''))=0 OR NEW.original_path NOT LIKE 'originals/%' OR NEW.display_path NOT LIKE 'reports/%' THEN RAISE EXCEPTION 'Invalid report photo paths'; END IF; RETURN NEW; END $$;
CREATE TRIGGER validate_report_photo BEFORE INSERT ON public.issue_photos FOR EACH ROW EXECUTE FUNCTION public.attach_report_photo();
CREATE TABLE public.civic_request_limits(key text PRIMARY KEY,hits integer NOT NULL DEFAULT 0,window_started_at timestamptz NOT NULL DEFAULT now());
GRANT ALL ON public.civic_request_limits TO service_role;
ALTER TABLE public.civic_request_limits ENABLE ROW LEVEL SECURITY;
CREATE OR REPLACE FUNCTION public.consume_civic_request(_key text,_limit integer) RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE n integer; BEGIN IF _limit NOT BETWEEN 1 AND 1000 OR length(_key)>150 THEN RETURN false; END IF; INSERT INTO public.civic_request_limits(key,hits) VALUES(_key,1) ON CONFLICT(key) DO UPDATE SET hits=CASE WHEN civic_request_limits.window_started_at<now()-interval '10 minutes' THEN 1 ELSE civic_request_limits.hits+1 END,window_started_at=CASE WHEN civic_request_limits.window_started_at<now()-interval '10 minutes' THEN now() ELSE civic_request_limits.window_started_at END RETURNING hits INTO n; RETURN n<=_limit; END $$;
REVOKE ALL ON FUNCTION public.consume_civic_request(text,integer) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.consume_civic_request(text,integer) TO service_role;
CREATE TABLE public.civic_ai_state(id text PRIMARY KEY DEFAULT 'classification',paused boolean NOT NULL DEFAULT false,reason text,updated_at timestamptz NOT NULL DEFAULT now());
GRANT ALL ON public.civic_ai_state TO service_role;
ALTER TABLE public.civic_ai_state ENABLE ROW LEVEL SECURITY;
CREATE OR REPLACE FUNCTION public.public_case_rows(_ref text DEFAULT NULL) RETURNS jsonb LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT coalesce(jsonb_agg(row),'[]'::jsonb) FROM (SELECT id,ref_code,title,summary,description,category,subcategory,severity,status,safety_warning,lat,lng,landmark,photo_url,department,support_count,sla_due_at,resolved_at,created_at,updated_at,duplicate_of,duplicate_candidate_id,routing_snapshot FROM public.issues WHERE _ref IS NULL OR ref_code=_ref ORDER BY created_at DESC LIMIT 1000) row $$;
REVOKE ALL ON FUNCTION public.public_case_rows(text) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.public_case_rows(text) TO anon,authenticated,service_role;
CREATE OR REPLACE FUNCTION public.public_case_events(_id uuid) RETURNS jsonb LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT coalesce(jsonb_agg(row ORDER BY row.created_at),'[]'::jsonb) FROM (SELECT id,issue_id,kind,from_status,to_status,CASE WHEN kind='created' THEN 'Report recorded in CivicFix. No government delivery recorded.' WHEN kind LIKE 'assignment_%' THEN 'Internal CivicFix assignment updated; not government acknowledgement.' WHEN kind LIKE 'duplicate_%' THEN 'Duplicate review recorded; original report retained.' WHEN kind='citizen_confirmed' THEN 'Reporter confirmed the fix.' WHEN kind='disputed' THEN 'Reporter requested another review.' WHEN kind LIKE 'evidence_%' THEN 'Evidence recorded by CivicFix staff.' ELSE 'Case updated by CivicFix staff.' END AS note,CASE WHEN actor_id IS NOT NULL THEN 'CivicFix staff' ELSE actor_label END AS actor_label,created_at FROM public.issue_events WHERE issue_id=_id) row $$;
REVOKE ALL ON FUNCTION public.public_case_events(uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.public_case_events(uuid) TO anon,authenticated,service_role;
CREATE OR REPLACE FUNCTION public.nearby_case_summary(_lat double precision,_lng double precision,_radius_m double precision DEFAULT 2000) RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ DECLARE result jsonb; BEGIN IF _lat IS NULL OR _lng IS NULL OR _radius_m IS NULL OR NOT (_lat BETWEEN -90 AND 90) OR NOT (_lng BETWEEN -180 AND 180) OR NOT (_radius_m BETWEEN 100 AND 10000) THEN RAISE EXCEPTION 'Invalid location or radius'; END IF; SELECT jsonb_build_object('total',count(*),'active',count(*) FILTER(WHERE status IN ('needs_classification','submitted','under_review','assigned','in_progress','reopened')),'resolved',count(*) FILTER(WHERE status IN ('resolved','closed')),'overdue',count(*) FILTER(WHERE status IN ('needs_classification','submitted','under_review','assigned','in_progress','reopened') AND sla_due_at<now()),'critical',count(*) FILTER(WHERE status IN ('needs_classification','submitted','under_review','assigned','in_progress','reopened') AND severity='critical'),'radius_m',_radius_m) INTO result FROM public.issues WHERE duplicate_of IS NULL AND 6371000*2*asin(least(1.0,sqrt(power(sin(radians(lat-_lat)/2),2)+cos(radians(_lat))*cos(radians(lat))*power(sin(radians(lng-_lng)/2),2))))<=_radius_m; RETURN result; END $$;
CREATE OR REPLACE FUNCTION public.validate_evidence_object() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NEW.storage_path NOT LIKE 'staff-evidence/'||NEW.issue_id::text||'/%' OR NOT EXISTS(SELECT 1 FROM storage.objects WHERE bucket_id='issue-photos' AND name=NEW.storage_path) THEN RAISE EXCEPTION 'Evidence photo must exist for this issue'; END IF; RETURN NEW; END $$;
CREATE TRIGGER validate_evidence_object BEFORE INSERT ON public.issue_evidence FOR EACH ROW EXECUTE FUNCTION public.validate_evidence_object();